// Simplified standalone Cloudflare Pages Function to bypass Next.js edge runtime bugs
import { jwtVerify } from "jose";

export const onRequestOptions: PagesFunction = async () => {
  return new Response(null, {
    status: 204,
    headers: {
      "Access-Control-Allow-Origin": "*",
      "Access-Control-Allow-Methods": "GET, POST, PUT, DELETE, OPTIONS",
      "Access-Control-Allow-Headers": "Content-Type, Authorization"
    }
  });
};

function base64ToArrayBuffer(base64: string) {
  const cleanBase64 = base64.replace(/[^A-Za-z0-9+/=]/g, "");
  const binaryString = atob(cleanBase64);
  const bytes = new Uint8Array(binaryString.length);
  for (let i = 0; i < binaryString.length; i++) {
    bytes[i] = binaryString.charCodeAt(i);
  }
  return bytes.buffer;
}

export const onRequestPost: PagesFunction<{ BUCKET: R2Bucket }> = async (context) => {
  const { request, env } = context;
  
  const CORS_HEADERS = {
    "Access-Control-Allow-Origin": "*",
    "Content-Type": "application/json"
  };

  try {
    // 1. JWT Authentication
    const cookieHeader = request.headers.get("Cookie") || "";
    const match = cookieHeader.match(/cms_session=([^;]+)/);
    const token = match ? match[1] : null;

    if (!token) {
        return new Response(JSON.stringify({ error: "Unauthorized: No token" }), { 
            status: 401, headers: CORS_HEADERS 
        });
    }

    // Determine secret (fallback to local dev if not found in env)
    // In Pages Functions, process.env might not be available, rely on context.env if bound, 
    // but AUTH_SECRET is usually set in .dev.vars or dashboard.
    const secretStr = (env as any).AUTH_SECRET || "change-me-in-env";
    const secret = new TextEncoder().encode(secretStr);

    try {
      const { payload } = await jwtVerify(token, secret);
      const role = payload.role as string;
      if (role !== "admin" && role !== "editor") {
         return new Response(JSON.stringify({ error: "Forbidden: Insufficient role" }), { 
            status: 403, headers: CORS_HEADERS 
        });
      }
    } catch (err) {
      return new Response(JSON.stringify({ error: "Unauthorized: Invalid token" }), { 
            status: 401, headers: CORS_HEADERS 
      });
    }

    // 2. Parse Body securely avoiding Next.js edge bugs
    const body = await request.json<any>();
    const { file_name, mime_type, file_content, size_bytes } = body;

    if (!file_content || !file_name || !mime_type) {
      return new Response(JSON.stringify({ error: "Missing required fields" }), { 
          status: 400, headers: CORS_HEADERS 
      });
    }

    const safeName = file_name.replace(/[^a-zA-Z0-9.\-_]/g, "_");
    const key = `uploads/${crypto.randomUUID()}-${safeName}`;
    
    const base64Data = file_content.includes(',') 
        ? file_content.split(',')[1] 
        : file_content;

    const fileBuffer = base64ToArrayBuffer(base64Data);

    await env.BUCKET.put(key, fileBuffer, {
      httpMetadata: { contentType: mime_type }
    });

    // Cloudflare dev base url or production URL
    let baseUrl = 'https://pub-844c31a0552a92bec753504a01b5f3bb.r2.dev';
    if (typeof process !== 'undefined' && process.env && process.env.R2_PUBLIC_BASE_URL) {
      baseUrl = process.env.R2_PUBLIC_BASE_URL;
    }

    const publicUrl = `${baseUrl}/${key}`;

    return new Response(JSON.stringify({
      success: true,
      key,
      publicUrl,
      file_name,
      mime_type,
      size_bytes: size_bytes || fileBuffer.byteLength
    }), { status: 200, headers: CORS_HEADERS });

  } catch (err: any) {
    console.error("Functions Upload Error:", err);
    return new Response(JSON.stringify({ error: `Upload failed: ${err.message}` }), { 
        status: 500, headers: CORS_HEADERS 
    });
  }
};
